// PIC Data Access Mechanism (x86/x64 Assembly Principle)

// 1. Get Program Counter (PC/RIP)
call .L1             // Push address of .L1 onto stack
.L1:
pop %rdi             // RDI = Current PC

// 2. Calculate Global Offset Table (GOT) Base Address
add $GOT_OFFSET, %rdi // RDI = GOT Base (Offset is fixed at link time)

// 3. Load Target Address from GOT
// GOT[i] holds the absolute runtime address of the variable
mov GOT_INDEX(%rdi), %rax // RAX = Address of global_var

// 4. Access the Data (Load independent of load address)
mov (%rax), %rcx
// ... Code continues
// RIP-relative addressing (x64 standard method) is similar:
// mov global_var@GOTPCREL(%rip), %rax
